  public function executeExcel()
  {
  	$c = new Criteria();
  	$parametros = '';
  	$titulo = '';  	
  	//Construir la consulta dependiendo del tipo de documentacion
  	$tipo_documentacion  = $this->getRequestParameter('tipo_documentacion_id');
  	//$this->titulo = TipoDocumentacionPeer::retrieveByPK($tipo_documentacion);
  	//fiLtros Para los Registros.
		  $c->addJoin(DocumentacionPeer::DOCUMENTACION_ID,RegistrosPeer::DOCUMENTACION_ID);
		  /*****************************************************************************************************/
    	  if($this->getRequestParameter('tipoescala_id')){
      		$c->add(RegistrosPeer::TIPOESCALA_ID,$this->getRequestParameter('tipoescala_id'));
	  		$parametros .= "&tipoescala_id=".$this->getRequestParameter('tipoescala_id');		
		  }
    	  /*****************************************************************************************************/
		  if($this->getRequestParameter('categoriaescala_id')){
      		$c->add(RegistrosPeer::CATEGORIAESCALA_ID,$this->getRequestParameter('categoriaescala_id'));
	  		$parametros .= "&categoriaescala_id=".$this->getRequestParameter('categoriaescala_id');		
		  }
         /******************************************************************************************************/
		 if($this->getRequestParameter('especialidadregistro_id')){
      		$c->add(RegistrosPeer::ESPECIALIDADREGISTRO_ID,$this->getRequestParameter('especialidadregistro_id'));
	  		$parametros .= "&especialidadregistro_id=".$this->getRequestParameter('especialidadregistro_id');		
		  }
    	 /******************************************************************************************************/
		 if($this->getRequestParameter('mencion_proyeccion')){
		 	$mencion = $this->getRequestParameter('mencion_proyeccion');
      		$c->add(RegistrosPeer::MENCION_PROYECCION,'%'.$mencion.'%',Criteria::LIKE);
	  		$parametros .= "&mencion_proyeccion=".$mencion;		
		  }
    	 /******************************************************************************************************/
    	 if($this->getRequestParameter('mencion_coordenadas')){
		 	$mencionPro = $this->getRequestParameter('mencion_coordenadas');
      		$c->add(RegistrosPeer::MENCION_COORDENADAS,'%'.$mencionPro.'%',Criteria::LIKE);
	  		$parametros .= "&mencion_coordenadas=".$mencionPro;		
		  }
    	 /******************************************************************************************************/		    		  	
		  
  	/**************************************************************************************************************/
	if($this->getRequestParameter('idioma_id')){
      $c->add(DocumentacionPeer::IDIOMA_ID,$this->getRequestParameter('idioma_id'));
	  $parametros .= "&idioma_id=".$this->getRequestParameter('idioma_id');		
	}
    /**************************************************************************************************************/
    if($this->getRequestParameter('titulo')){
      $c->add(DocumentacionPeer::TITULO,'%'.$this->getRequestParameter('titulo').'%',Criteria::LIKE);
	  $parametros .= "&titulo=".$this->getRequestParameter('titulo');		
	}
    /**************************************************************************************************************/
    if($this->getRequestParameter('codigoBarras')){
      $c->add(DocumentacionPeer::CODIGO_BARRAS,'%'.$this->getRequestParameter('codigoBarras').'%',Criteria::LIKE);
	  $parametros .= "&codigoBarras=".$this->getRequestParameter('codigoBarras');		
	}
    /**************************************************************************************************************/
    if($this->getRequestParameter('ubicacion')){
      $c->add(DocumentacionPeer::UBICACION,'%'.$this->getRequestParameter('ubicacion').'%',Criteria::LIKE);
	  $parametros .= "&ubicacion=".$this->getRequestParameter('ubicacion');		
	}
    /**************************************************************************************************************/            
    
    $c->add(DocumentacionPeer::ESTADODOCUMENTACION_ID,1);
	$c->add(DocumentacionPeer::TIPODOCUMENTACION_ID,$tipo_documentacion);
	$c->addDescendingOrderByColumn(DocumentacionPeer::DOCUMENTACION_ID);  	  	  	
  	/*************************************************************************************************************/
	//$pager = new sfPropelPager('Registros', 10);	
	//$pager->setCriteria($c);        
	//$pager->setPage($this->getRequestParameter('page', 1));
	//$pager->init();
	//$this->pager = $pager;
	$pager = RegistrosPeer::doSelect($c);
	$this->parametros = $parametros;
	$this->tipo_documentacion =$tipo_documentacion;
	$this->username = $this->getUser()->getAttribute('username', '', 'subscriber');				    
	/*************************************************************************************************************/
	$userInventariador = array();
	$userCreador = array();
	
	foreach($pager as $manual_tecnico){
		/***************************************Consulta para el inventariador**********************************/    		$c = new Criteria();
		$c->add(UdUsuarioDocumentacionPeer::DOCUMENTACION_ID,$manual_tecnico->getDocumentacionId());
		$c->add(UdUsuarioDocumentacionPeer::RUSUARIODOCUMENTACION_ID,2);	
		$userInv = UdUsuarioDocumentacionPeer::doSelectOne($c);
		$userInventariador[] = $userInv->getUsuario();	
		/*******************************************************************************************************/
		
		/***************************************Consulta para el Creador****************************************/    
	    $b = new Criteria();
		$b->add(UdUsuarioDocumentacionPeer::DOCUMENTACION_ID,$manual_tecnico->getDocumentacionId());
		$b->add(UdUsuarioDocumentacionPeer::RUSUARIODOCUMENTACION_ID,1);	
		$userCre = UdUsuarioDocumentacionPeer::doSelectOne($b);	
		$userCreador[] = $userCre->getUsuario();
		/*******************************************************************************************************/
	}
	$this->usuarioInv = $userInventariador;
	$this->usuarioCre = $userCreador;	
	$this->pager = $pager;
	/*************************************************************************************************************/
  }
  
  public function executeDelete()
  {
    $registros = RegistrosPeer::retrieveByPk($this->getRequestParameter('registros_id'));

    $this->forward404Unless($registros);

    $registros->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/registros/list');
  }
